\begin{document}
\sheettitle{Fiche 5}{Séries chronologiques -- ÉNONCÉ}{Badr ABOUFARASSE, PhD. -- Année universitaire 2026--2027}

\exercise{Exercice 1 -- Composantes et modèles d'une série chronologique}
\begin{enumerate}
\item Associer chaque situation à une composante : tendance générale, mouvement lié à une récession, pic récurrent au même trimestre, choc exceptionnel non prévisible.
\item Écrire le modèle additif complet et le modèle multiplicatif complet avec les composantes $T,C,S,R$.
\item Rappeler l'hypothèse utilisée dans la suite du cours lorsque les composantes cyclique et résiduelle sont négligées.
\end{enumerate}

\exercise{Exercice 2 -- Moyenne mobile centrée d'ordre 4}
On observe les huit premières ventes trimestrielles :
\[
18,\ 26,\ 20,\ 35,\ 25,\ 36,\ 28,\ 48.
\]
\begin{enumerate}
\item Calculer les moyennes mobiles simples d'ordre 4 sur les fenêtres 1--4, 2--5, 3--6, 4--7 et 5--8.
\item Centrer ces moyennes pour obtenir les moyennes mobiles centrées aux périodes 3 à 6.
\item Expliquer pourquoi une moyenne d'ordre pair doit être centrée.
\end{enumerate}

\exercise{Exercice 3 -- Décomposition multiplicative et prévision trimestrielle}
Les ventes trimestrielles (en centaines d'euros) sont :
\begin{center}
\begin{tabular}{c|rrrr}
Année&T1&T2&T3&T4\\\hline
2012&18&26&20&35\\
2013&25&36&28&48\\
2014&38&52&40&65
\end{tabular}
\end{center}
On utilise un modèle multiplicatif et le trend
\[
T(t)=3t+15,40,\qquad t=1\ \text{pour T1 2012}.
\]
\begin{enumerate}
\item Représenter la série et identifier la saisonnalité.
\item Détailler le calcul des deux premières moyennes mobiles centrées d'ordre 4.
\item Calculer les deux premières valeurs de $S=Y/T$ et expliquer comment on obtient les quatre moyennes saisonnières $Moy(S)$.
\item À partir des moyennes saisonnières arrondies $0,90$, $1,15$, $0,81$, $1,25$, rectifier les coefficients pour que leur moyenne soit égale à 1.
\item Calculer les prévisions désaisonnalisées puis saisonnalisées pour 2015 ($t=13,14,15,16$).
\end{enumerate}

\end{document}

